"""Inspect the workspace: list files and check for existing SQLite databases."""
import os
import sqlite3

HERE = os.path.dirname(os.path.abspath(__file__))

print("Workspace contents of:", HERE)
for name in sorted(os.listdir(HERE)):
    full = os.path.join(HERE, name)
    kind = "dir " if os.path.isdir(full) else "file"
    print(f"  [{kind}] {name}")

print("\nSQLite databases found:")
for name in sorted(os.listdir(HERE)):
    if name.endswith((".db", ".sqlite", ".sqlite3")):
        full = os.path.join(HERE, name)
        try:
            with sqlite3.connect(full) as conn:
                tables = [
                    row[0]
                    for row in conn.execute(
                        "SELECT name FROM sqlite_master WHERE type='table' ORDER BY name"
                    )
                ]
            print(f"  {name}: tables={tables}")
        except sqlite3.Error as exc:
            print(f"  {name}: could not open ({exc})")

